1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
crypto: ccp - Fix a crash due to incorrect cleanup usage of
 kfree

Annotating a local pointer variable, which will be assigned with the
kmalloc-family functions, with the `__cleanup(kfree)` attribute will
make the address of the local variable, rather than the address returned
by kmalloc, passed to kfree directly and lead to a crash due to invalid
deallocation of stack address. According to other places in the repo,
the correct usage should be `__free(kfree)`. The code coincidentally
compiled because the parameter type `void *` of kfree is compatible with
the desired type `struct { ... } **`.

Fixes: a71475582ada ("crypto: ccp - reduce stack usage in ccp_run_aes_gcm_cmd")
Signed-off-by: Ella Ma <alansnape3058@gmail.com>
Acked-by: Tom Lendacky <thomas.lendacky@gmail.com>
Signed-off-by: Herbert Xu <herbert@gondor.apana.org.au>

Here is the root cause:
The bug was caused by using `__cleanup(kfree)` to annotate a local pointer variable that was allocated with `kzalloc`. This attribute passes the address of the local variable (a stack address) to `kfree` instead of the dynamically allocated pointer, resulting in a crash due to invalid deallocation of stack memory. The correct attribute is `__free(kfree)`, which properly passes the pointer value to `kfree` when the variable goes out of scope.

Here is the patch:

 static noinline_for_stack int
 ccp_run_aes_gcm_cmd(struct ccp_cmd_queue *cmd_q, struct ccp_cmd *cmd)
 {
 	struct ccp_aes_engine *aes = &cmd->u.aes;
 	struct {
 		struct ccp_dm_workarea key;
 		struct ccp_dm_workarea ctx;
 		struct ccp_dm_workarea final;
 		struct ccp_dm_workarea tag;
 		struct ccp_data src;
 		struct ccp_data dst;
 		struct ccp_data aad;
 		struct ccp_op op;
-	} *wa __cleanup(kfree) = kzalloc(sizeof *wa, GFP_KERNEL);
+	} *wa __free(kfree) = kzalloc(sizeof(*wa), GFP_KERNEL);
 	unsigned int dm_offset;
 	unsigned int authsize;
 	unsigned int jobid;
 	unsigned int ilen;
 	bool in_place = true; /* Default value */
 	__be64 *final;
 	int ret;

 	struct scatterlist *p_inp, sg_inp[2];
 	struct scatterlist *p_tag, sg_tag[2];
 	struct scatterlist *p_outp, sg_outp[2];
 	struct scatterlist *p_aad;

 	if (!wa)
 		return -ENOMEM;

 	if (!aes->iv)
 		return -EINVAL;

 	if (!((aes->key_len == AES_KEYSIZE_128) ||
 		(aes->key_len == AES_KEYSIZE_192) ||
 		(aes->key_len == AES_KEYSIZE_256)))
 		return -EINVAL;

 	if (!aes->key) /* Gotta have a key SGL */
 		return -EINVAL;

 	/* Zero defaults to 16 bytes, the maximum size */
 	authsize = aes->authsize ? aes->authsize : AES_BLOCK_SIZE;
 	switch (authsize) {
 	case 16:
 	case 15:
 	case 14:
 	case 13:
 	case 12:
 	case 8:
 	case 4:
 		break;
 	default:
 		return -EINVAL;
 	}

 	/* First, decompose the source buffer into AAD & PT,
 	 * and the destination buffer into AAD, CT & tag, or
 	 * the input into CT & tag.
 	 * It is expected that the input and output SGs will
 	 * be valid, even if the AAD and input lengths are 0.
 	 */
 	p_aad = aes->src;
 	p_inp = scatterwalk_ffwd(sg_inp, aes->src, aes->aad_len);
 	p_outp = scatterwalk_ffwd(sg_outp, aes->dst, aes->aad_len);
 	if (aes->action == CCP_AES_ACTION_ENCRYPT) {
 		ilen = aes->src_len;
 		p_tag = scatterwalk_ffwd(sg_tag, p_outp, ilen);
 	} else {
 		/* Input length for decryption includes tag */
 		ilen = aes->src_len - authsize;
 		p_tag = scatterwalk_ffwd(sg_tag, p_inp, ilen);
 	}

 	jobid = CCP_NEW_JOBID(cmd_q->ccp);

 	memset(&wa->op, 0, sizeof(wa->op));
 	wa->op.cmd_q = cmd_q;
 	wa->op.jobid = jobid;
 	wa->op.sb_key = cmd_q->sb_key; /* Pre-allocated */
 	wa->op.sb_ctx = cmd_q->sb_ctx; /* Pre-allocated */
 	wa->op.init = 1;
 	wa->op.u.aes.type = aes->type;

 	/* Copy the key to the LSB */
 	ret = ccp_init_dm_workarea(&wa->key, cmd_q,
 				   CCP_AES_CTX_SB_COUNT * CCP_SB_BYTES,
 				   DMA_TO_DEVICE);
 	if (ret)
 		return ret;

 	dm_offset = CCP_SB_BYTES - aes->key_len;
 	ret = ccp_set_dm_area(&wa->key, dm_offset, aes->key, 0, aes->key_len);
 	if (ret)
 		goto e_key;
 	ret = ccp_copy_to_sb(cmd_q, &wa->key, wa->op.jobid, wa->op.sb_key,
 			     CCP_PASSTHRU_BYTESWAP_256BIT);
 	if (ret) {
 		cmd->engine_error = cmd_q->cmd_error;
 		goto e_key;
 	}

 	/* Copy the context (IV) to the LSB.
 	 * There is an assumption here that the IV is 96 bits in length, plus
 	 * a nonce of 32 bits. If no IV is present, use a zeroed buffer.
 	 */
 	ret = ccp_init_dm_workarea(&wa->ctx, cmd_q,
 				   CCP_AES_CTX_SB_COUNT * CCP_SB_BYTES,
 				   DMA_BIDIRECTIONAL);
 	if (ret)
 		goto e_key;

 	dm_offset = CCP_AES_CTX_SB_COUNT * CCP_SB_BYTES - aes->iv_len;
 	ret = ccp_set_dm_area(&wa->ctx, dm_offset, aes->iv, 0, aes->iv_len);
 	if (ret)
 		goto e_ctx;

 	ret = ccp_copy_to_sb(cmd_q, &wa->ctx, wa->op.jobid, wa->op.sb_ctx,
 			     CCP_PASSTHRU_BYTESWAP_256BIT);
 	if (ret) {
 		cmd->engine_error = cmd_q->cmd_error;
 		goto e_ctx;
 	}

 	wa->op.init = 1;
 	if (aes->aad_len > 0) {
 		/* Step 1: Run a GHASH over the Additional Authenticated Data */
 		ret = ccp_init_data(&wa->aad, cmd_q, p_aad, aes->aad_len,
 				    AES_BLOCK_SIZE,
 				    DMA_TO_DEVICE);
 		if (ret)
 			goto e_ctx;

 		wa->op.u.aes.mode = CCP_AES_MODE_GHASH;
 		wa->op.u.aes.action = CCP_AES_GHASHAAD;

 		while (wa->aad.sg_wa.bytes_left) {
 			ccp_prepare_data(&wa->aad, NULL, &wa->op, AES_BLOCK_SIZE, true);

 			ret = cmd_q->ccp->vdata->perform->aes(&wa->op);
 			if (ret) {
 				cmd->engine_error = cmd_q->cmd_error;
 				goto e_aad;
 			}

 			ccp_process_data(&wa->aad, NULL, &wa->op);
 			wa->op.init = 0;
 		}
 	}

 	wa->op.u.aes.mode = CCP_AES_MODE_GCTR;
 	wa->op.u.aes.action = aes->action;

 	if (ilen > 0) {
 		/* Step 2: Run a GCTR over the plaintext */
 		in_place = (sg_virt(p_inp) == sg_virt(p_outp)) ? true : false;

 		ret = ccp_init_data(&wa->src, cmd_q, p_inp, ilen,
 				    AES_BLOCK_SIZE,
 				    in_place ? DMA_BIDIRECTIONAL
 					     : DMA_TO_DEVICE);
 		if (ret)
 			goto e_aad;

 		if (in_place) {
 			wa->dst = wa->src;
 		} else {
 			ret = ccp_init_data(&wa->dst, cmd_q, p_outp, ilen,
 					    AES_BLOCK_SIZE, DMA_FROM_DEVICE);
 			if (ret)
 				goto e_src;
 		}

 		wa->op.soc = 0;
 		wa->op.eom = 0;
 		wa->op.init = 1;
 		while (wa->src.sg_wa.bytes_left) {
 			ccp_prepare_data(&wa->src, &wa->dst, &wa->op, AES_BLOCK_SIZE, true);
 			if (!wa->src.sg_wa.bytes_left) {
 				unsigned int nbytes = ilen % AES_BLOCK_SIZE;

 				if (nbytes) {
 					wa->op.eom = 1;
 					wa->op.u.aes.size = (nbytes * 8) - 1;
 				}
 			}

 			ret = cmd_q->ccp->vdata->perform->aes(&wa->op);
 			if (ret) {
 				cmd->engine_error = cmd_q->cmd_error;
 				goto e_dst;
 			}

 			ccp_process_data(&wa->src, &wa->dst, &wa->op);
 			wa->op.init = 0;
 		}
 	}

 	/* Step 3: Update the IV portion of the context with the original IV */
 	ret = ccp_copy_from_sb(cmd_q, &wa->ctx, wa->op.jobid, wa->op.sb_ctx,
 			       CCP_PASSTHRU_BYTESWAP_256BIT);
 	if (ret) {
 		cmd->engine_error = cmd_q->cmd_error;
 		goto e_dst;
 	}

 	ret = ccp_set_dm_area(&wa->ctx, dm_offset, aes->iv, 0, aes->iv_len);
 	if (ret)
 		goto e_dst;

 	ret = ccp_copy_to_sb(cmd_q, &wa->ctx, wa->op.jobid, wa->op.sb_ctx,
 			     CCP_PASSTHRU_BYTESWAP_256BIT);
 	if (ret) {
 		cmd->engine_error = cmd_q->cmd_error;
 		goto e_dst;
 	}

 	/* Step 4: Concatenate the lengths of the AAD and source, and
 	 * hash that 16 byte buffer.
 	 */
 	ret = ccp_init_dm_workarea(&wa->final, cmd_q, AES_BLOCK_SIZE,
 				   DMA_BIDIRECTIONAL);
 	if (ret)
 		goto e_dst;
 	final = (__be64 *)wa->final.address;
 	final[0] = cpu_to_be64(aes->aad_len * 8);
 	final[1] = cpu_to_be64(ilen * 8);

 	memset(&wa->op, 0, sizeof(wa->op));
 	wa->op.cmd_q = cmd_q;
 	wa->op.jobid = jobid;
 	wa->op.sb_key = cmd_q->sb_key; /* Pre-allocated */
 	wa->op.sb_ctx = cmd_q->sb_ctx; /* Pre-allocated */
 	wa->op.init = 1;
 	wa->op.u.aes.type = aes->type;
 	wa->op.u.aes.mode = CCP_AES_MODE_GHASH;
 	wa->op.u.aes.action = CCP_AES_GHASHFINAL;
 	wa->op.src.type = CCP_MEMTYPE_SYSTEM;
 	wa->op.src.u.dma.address = wa->final.dma.address;
 	wa->op.src.u.dma.length = AES_BLOCK_SIZE;
 	wa->op.dst.type = CCP_MEMTYPE_SYSTEM;
 	wa->op.dst.u.dma.address = wa->final.dma.address;
 	wa->op.dst.u.dma.length = AES_BLOCK_SIZE;
 	wa->op.eom = 1;
 	wa->op.u.aes.size = 0;
 	ret = cmd_q->ccp->vdata->perform->aes(&wa->op);
 	if (ret)
 		goto e_final_wa;

 	if (aes->action == CCP_AES_ACTION_ENCRYPT) {
 		/* Put the ciphered tag after the ciphertext. */
 		ccp_get_dm_area(&wa->final, 0, p_tag, 0, authsize);
 	} else {
 		/* Does this ciphered tag match the input? */
 		ret = ccp_init_dm_workarea(&wa->tag, cmd_q, authsize,
 					   DMA_BIDIRECTIONAL);
 		if (ret)
 			goto e_final_wa;
 		ret = ccp_set_dm_area(&wa->tag, 0, p_tag, 0, authsize);
 		if (ret) {
 			ccp_dm_free(&wa->tag);
 			goto e_final_wa;
 		}

 		ret = crypto_memneq(wa->tag.address, wa->final.address,
 				    authsize) ? -EBADMSG : 0;
 		ccp_dm_free(&wa->tag);
 	}

 e_final_wa:
 	ccp_dm_free(&wa->final);

 e_dst:
 	if (ilen > 0 && !in_place)
 		ccp_free_data(&wa->dst, cmd_q);

 e_src:
 	if (ilen > 0)
 		ccp_free_data(&wa->src, cmd_q);

 e_aad:
 	if (aes->aad_len)
 		ccp_free_data(&wa->aad, cmd_q);

 e_ctx:
 	ccp_dm_free(&wa->ctx);

 e_key:
 	ccp_dm_free(&wa->key);

 	return ret;
 }



